insert into play_questions (id, pillar, tags, tier, type, content, reel_id, chapter_slug, status, source) values
  ('budget-needs-vs-wants-001','budget', array['needs-vs-wants','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"In \"Peter Learns Needs vs Wants\", what simple test does Stewie give to tell a need from a want?","options":["Is it cheaper than ₹500?","Can I get through the month without it?","Do all my friends already have it?","Will I enjoy it today?"],"answer":"B","explanation":"A need is something you can''t get through the month without. A want is just nice to have."}}'::jsonb, 'budget-needs-vs-wants',null,'draft','ai'),
  ('budget-50-30-20-001','budget', array['50-30-20','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"In the reel, Stewie splits ₹2,000 of monthly money using the 50-30-20 rule. What is the split?","options":["₹1,000 wants, ₹600 needs, ₹400 savings","₹700 needs, ₹600 wants, ₹700 savings","₹1,000 needs, ₹600 wants, ₹400 savings","₹600 needs, ₹400 wants, ₹1,000 savings"],"answer":"C","explanation":"50% of ₹2,000 is ₹1,000 for needs, 30% is ₹600 for wants and 20% is ₹400 for savings."}}'::jsonb, 'budget-50-30-20',null,'draft','ai'),
  ('budget-tracking-spending-001','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"In \"Peter''s Chai Math\", Stewie says spending ₹20 a day on chai adds up to how much in a month?","options":["₹200","₹2,000","₹7,300","₹600"],"answer":"D","explanation":"₹20 a day for 30 days is ₹600 a month. ₹7,300 is what it adds up to in a whole year."}}'::jsonb, 'budget-chai-math',null,'draft','ai'),
  ('budget-needs-vs-wants-002','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a need for a student who takes the bus to school?","options":["Monthly bus pass","New wireless earphones","A skin for an online game","Biryani with friends every Friday"],"answer":"A","explanation":"Without the bus pass the student can''t get to school. The others are nice to have but not needed to get through the month."}}'::jsonb, null,'budget-needs-vs-wants','draft','ai'),
  ('budget-needs-vs-wants-003','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Kavya''s phone works fine, but a new model has just launched. For Kavya, buying the new phone is:","options":["A need, because everyone uses phones","A need, because newer is always better","An emergency expense","A want, because her phone already works"],"answer":"D","explanation":"Her current phone already does the job, so the new one is nice to have, not something she can''t do without."}}'::jsonb, null,'budget-needs-vs-wants','draft','ai'),
  ('budget-needs-vs-wants-004','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"Food is a need. Which of these food spends is a want?","options":["Rice and dal at home","A lunch tiffin for school","Pizza with friends every weekend","Milk for the family"],"answer":"C","explanation":"Eating is a need, but eating out with friends every weekend is extra. You can get through the month without it."}}'::jsonb, null,'budget-needs-vs-wants','draft','ai'),
  ('budget-needs-vs-wants-005','budget', array['needs-vs-wants','pocket-money'], 'bronze','mcq', '{"en":{"prompt":"Arjun has just got his monthly pocket money. In what order should he spend it?","options":["Wants first, then needs with the rest","Needs first, then wants with the leftovers","Half on needs, half on wants","Whatever feels most urgent that day"],"answer":"B","explanation":"Paying for needs first makes sure the important things are covered. Wants are paid from whatever is left."}}'::jsonb, null,'budget-needs-vs-wants','draft','ai'),
  ('budget-needs-vs-wants-006','budget', array['needs-vs-wants'], 'bronze','mcq', '{"en":{"prompt":"A phone recharge is a need for Neha, who attends online classes, but a want for her cousin. Why can this happen?","options":["Prices are different from shop to shop","Wants turn into needs if you like them enough","Needs depend on what each person''s life truly requires","Only adults have real needs"],"answer":"C","explanation":"Whether something is a need depends on the person''s situation. Neha needs the recharge for school; her cousin can manage without it."}}'::jsonb, null,'budget-needs-vs-wants','draft','ai'),
  ('budget-tracking-spending-002','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"What is the main purpose of tracking your spending?","options":["To see where your money actually goes","To make your income go up","To prove you never buy wants","So you no longer need a budget"],"answer":"A","explanation":"Tracking shows you exactly where your money goes. Then you can decide what to change."}}'::jsonb, null,null,'draft','ai'),
  ('budget-tracking-spending-003','budget', array['tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"Why do small UPI payments often go unnoticed?","options":["UPI payments are always free","One tap, no cash leaves your hand, so it feels invisible","UPI hides payments from your history","Small payments don''t count in a budget"],"answer":"B","explanation":"With UPI you never see cash leave your hand, so small spends don''t feel real. They still add up."}}'::jsonb, null,null,'draft','ai'),
  ('budget-50-30-20-002','budget', array['50-30-20'], 'bronze','mcq', '{"en":{"prompt":"In the 50-30-20 rule, what is the 20% part for?","options":["Wants","Needs","Bills and EMIs","Savings"],"answer":"D","explanation":"The rule puts 50% on needs, 30% on wants and 20% into savings."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-001','budget', array['pocket-money'], 'bronze','mcq', '{"en":{"prompt":"What is a budget?","options":["A plan for how you will use your money","A list of what you bought last year","A rule that bans spending on fun","The money left at the end of the month"],"answer":"A","explanation":"A budget is a plan made in advance for how your money will be used. It can include fun, as long as it is planned."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-001','budget', array['bills-and-emi'], 'bronze','mcq', '{"en":{"prompt":"What is an EMI?","options":["A one-time discount when you buy","A fee charged on every UPI payment","A fixed monthly payment to repay a loan","Interest you earn on your savings"],"answer":"C","explanation":"EMI means Equated Monthly Instalment. It is the same amount paid every month until a loan is repaid."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-002','budget', array['bills-and-emi'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a fixed bill that many families pay every month?","options":["A movie ticket","A birthday gift","Street food on the way home","House rent"],"answer":"D","explanation":"Rent is the same amount, due every month. The others change or happen only now and then."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-002','budget', array['pocket-money','tracking-spending'], 'bronze','mcq', '{"en":{"prompt":"What does \"pay yourself first\" mean?","options":["Move your savings aside as soon as money comes in","Buy something for yourself before paying bills","Spend first, then save whatever is left","Pay friends back before buying anything"],"answer":"A","explanation":"Saving first, on the day money arrives, means it doesn''t get spent by accident. You then spend what''s left."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-003','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"In \"Peter Falls for ''No-Cost EMI''\", why does Stewie say no-cost EMI is often not really free?","options":["The price doubles after the first month","You must pay the full price upfront","You may still pay a processing fee and GST on interest","The shop keeps your phone until you finish paying"],"answer":"C","explanation":"The shop''s discount covers the interest, but a processing fee and GST on the interest are often still charged. So \"no-cost\" can mean some cost."}}'::jsonb, 'budget-no-cost-emi',null,'draft','ai'),
  ('budget-bills-and-emi-004','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"Peter''s credit card bill is ₹20,000. He pays only the ₹1,000 \"minimum due\". What happens to the rest?","options":["It is forgiven by the card company","It is charged interest, which keeps growing","It waits interest-free until next month","It is taken from his savings automatically"],"answer":"B","explanation":"Paying the minimum only avoids a late fee. The unpaid ₹19,000 is charged high interest every month, and interest gets added on interest."}}'::jsonb, 'budget-minimum-due',null,'draft','ai'),
  ('budget-pocket-money-003','budget', array['pocket-money','tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Rahul''s ₹2,000 pocket money runs out by the 20th every month, and he isn''t sure why. What is the most useful first step?","options":["Ask his parents for more money","Write down every spend for a month","Borrow from friends till month end","Stop buying any food outside at all"],"answer":"B","explanation":"He can''t fix a leak he can''t see. Tracking every spend shows where the money really goes, so he can cut the right things."}}'::jsonb, null,'budget-pocket-money-plan','draft','ai'),
  ('budget-50-30-20-003','budget', array['50-30-20','pocket-money'], 'silver','mcq', '{"en":{"prompt":"Sneha gets ₹3,000 a month and wants to follow the 50-30-20 rule. How much goes to savings?","options":["₹300","₹900","₹1,500","₹600"],"answer":"D","explanation":"Savings are 20% of the money. 20% of ₹3,000 is ₹600."}}'::jsonb, null,'budget-pocket-money-plan','draft','ai'),
  ('budget-tracking-spending-004','budget', array['tracking-spending','pocket-money'], 'silver','mcq', '{"en":{"prompt":"On Sunday, Imran checks his UPI history and finds he spent ₹450 on snacks this week. What is a sensible next step?","options":["Set a weekly snack limit and keep checking","Delete the history so it doesn''t bother him","Ignore it, because small spends don''t matter","Spend more next week to even it out"],"answer":"A","explanation":"A limit turns what he learned into a plan, and checking each week shows if it is working."}}'::jsonb, null,'budget-pocket-money-plan','draft','ai'),
  ('budget-pocket-money-004','budget', array['pocket-money'], 'silver','mcq', '{"en":{"prompt":"Divya gets ₹1,800 on the 1st. Her ₹600 bus pass must be paid on the 10th. Which plan keeps her from running short?","options":["Keep ₹600 aside for the pass on day 1","Spend freely and pay from what is left","Pay the pass only if money is left","Use the pass money now and borrow later"],"answer":"A","explanation":"Setting the bus pass money aside first means a need is covered before any of it is spent on wants."}}'::jsonb, null,'budget-pocket-money-plan','draft','ai'),
  ('budget-50-30-20-004','budget', array['50-30-20','pocket-money'], 'silver','mcq', '{"en":{"prompt":"Kiran gets ₹2,500 a month. Her needs cost ₹1,500, which is more than 50%. How can she adjust her 50-30-20 plan?","options":["Stop saving and keep wants the same","Skip a need, like her exam fee","Drop the plan and spend as she likes","Spend less on wants so needs and savings stay covered"],"answer":"D","explanation":"50-30-20 is a guide, not a fixed law. When needs cost more, the extra should come out of wants first."}}'::jsonb, null,'budget-pocket-money-plan','draft','ai'),
  ('budget-needs-vs-wants-007','budget', array['needs-vs-wants'], 'silver','mcq', '{"en":{"prompt":"Ravi has ₹500 left. His phone recharge for online classes costs ₹299, and a concert ticket costs ₹450. Which is the needs-first choice?","options":["Buy the ticket and skip the recharge","Borrow ₹250 to pay for both","Recharge now and save the rest toward the ticket","Spend ₹250 on each"],"answer":"C","explanation":"The recharge is needed for his classes, so it comes first. The ticket is a want he can save up for."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-005','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"A shop offers a phone \"for just ₹999 a month\". Before agreeing, which question matters most?","options":["What is the total I will pay?","Is the monthly amount under ₹1,000?","Do my friends also buy on EMI?","What colours does the phone come in?"],"answer":"A","explanation":"A small monthly amount can hide a large total. Knowing the total, with fees, tells you the true cost."}}'::jsonb, null,null,'draft','ai'),
  ('budget-tracking-spending-005','budget', array['tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Which kind of spending is easiest to lose track of?","options":["One large exam fee","Many small spends every day","A fixed monthly rent","A yearly school fee"],"answer":"B","explanation":"Big payments are easy to remember. Small daily spends feel like nothing but quietly add up."}}'::jsonb, null,null,'draft','ai'),
  ('budget-needs-vs-wants-008','budget', array['needs-vs-wants'], 'silver','mcq', '{"en":{"prompt":"A sale offers 40% off shoes Ajay doesn''t need. He has ₹1,000 saved for his exam fee. What is the sound reasoning?","options":["Buy now, because 40% off saves money","Use the exam money now and refill it later","Buy two pairs to save even more","A discount on a want is still spending"],"answer":"D","explanation":"A discount only saves money on something you were going to buy anyway. Using exam fee money on a want puts a need at risk."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-005','budget', array['pocket-money'], 'silver','mcq', '{"en":{"prompt":"Fatima earns ₹800 from tuitions in some months and nothing in others. How should she plan her spending?","options":["Plan around her best month","Spend it all as soon as it comes","Plan around the low months, not the best ones","Plan on the average and borrow the gap"],"answer":"C","explanation":"If she plans for the months with no income, she won''t run short when they come. Extra in good months can be saved."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-006','budget', array['bills-and-emi'], 'silver','mcq', '{"en":{"prompt":"Suresh''s family pays rent, electricity and a ₹2,000 loan EMI every month. Why should these come first in their budget?","options":["They must be paid every month, with fines if late","They are wants that can wait","They change every day","They earn interest for the family"],"answer":"A","explanation":"These are fixed bills that are due every month. Missing them brings late fees and other trouble, so they are planned first."}}'::jsonb, null,null,'draft','ai'),
  ('budget-50-30-20-005','budget', array['50-30-20'], 'silver','mcq', '{"en":{"prompt":"Which of these belongs in the 30% \"wants\" part of a 50-30-20 budget?","options":["A bus pass","A movie with friends","An exam fee","Money for emergencies"],"answer":"B","explanation":"A movie is nice to have but not needed. Bus pass and exam fee are needs, and emergency money is savings."}}'::jsonb, null,null,'draft','ai'),
  ('budget-tracking-spending-006','budget', array['tracking-spending'], 'silver','mcq', '{"en":{"prompt":"Lakshmi wants to track her spending but keeps forgetting. Which habit is easiest to keep up?","options":["Check it once a year","Track only purchases above ₹1,000","Track only the cash she spends","Check her payment history for a few minutes each week"],"answer":"D","explanation":"A short weekly check catches small spends before they pile up, and it is quick enough to stick with."}}'::jsonb, null,null,'draft','ai'),
  ('budget-tracking-spending-007','budget', array['tracking-spending'], 'gold','mcq', '{"en":{"prompt":"Meena buys a ₹40 cold drink every school day. Assume 24 school days a month. How much does this cost her in a year?","options":["₹960","₹4,800","₹11,520","₹14,600"],"answer":"C","explanation":"₹40 × 24 = ₹960 a month, and ₹960 × 12 = ₹11,520 a year."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-007','budget', array['bills-and-emi'], 'gold','mcq', '{"en":{"prompt":"A ₹12,000 phone is offered at ₹1,100 a month for 12 months. Assume no other fees. How much more than the price do you pay?","options":["₹1,200","₹1,100","₹100","₹13,200"],"answer":"A","explanation":"₹1,100 × 12 = ₹13,200 in total. ₹13,200 − ₹12,000 = ₹1,200 extra."}}'::jsonb, null,null,'draft','ai'),
  ('budget-50-30-20-006','budget', array['50-30-20','pocket-money'], 'gold','mcq', '{"en":{"prompt":"Nikhil gets ₹4,000 a month and follows the 50-30-20 rule. He wants a ₹4,800 cycle and saves only his savings share for it. How many months will it take?","options":["4 months","8 months","12 months","6 months"],"answer":"D","explanation":"His savings share is 20% of ₹4,000 = ₹800 a month. ₹4,800 ÷ ₹800 = 6 months."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-006','budget', array['pocket-money','tracking-spending'], 'gold','mcq', '{"en":{"prompt":"Anjali gets ₹2,400 for a 30-day month. On day 1 she pays ₹600 for a bus pass and ₹300 for a recharge, and saves ₹300. How much can she spend each day after that?","options":["₹50","₹40","₹60","₹80"],"answer":"B","explanation":"₹2,400 − ₹600 − ₹300 − ₹300 = ₹1,200 left. ₹1,200 ÷ 30 days = ₹40 a day."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-008','budget', array['bills-and-emi'], 'gold','mcq', '{"en":{"prompt":"A credit card charges 3% a month on the unpaid balance. Varun owes ₹10,000, pays nothing and spends nothing more. Ignore fees. What does he owe after 2 months?","options":["₹10,600","₹10,300","₹10,609","₹16,000"],"answer":"C","explanation":"After month 1 he owes ₹10,000 + ₹300 = ₹10,300. In month 2, 3% of ₹10,300 is ₹309, making ₹10,609, because interest is charged on interest."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-009','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"A laptop costs ₹15,000 in cash. A \"no-cost EMI\" plan is ₹2,500 a month for 6 months plus a ₹499 processing fee. Which statement is true?","options":["Both options cost exactly the same","EMI costs ₹499 more, but cash stays free for now","EMI is cheaper because you pay later","Cash costs more because you pay all at once"],"answer":"B","explanation":"₹2,500 × 6 = ₹15,000, plus the ₹499 fee makes ₹15,499. The EMI keeps money in hand for longer, but it costs more in total."}}'::jsonb, null,null,'draft','ai'),
  ('budget-needs-vs-wants-009','budget', array['needs-vs-wants'], 'platinum','mcq', '{"en":{"prompt":"Meera has one free afternoon. A paid shift earns ₹900 but costs ₹150 in travel. Tutoring earns ₹650. A workshop is free. She picks the workshop. In money, what does she give up?","options":["₹650, from tutoring","₹900, the shift''s full pay","₹1,400, both jobs added together","₹750, from the best option she skipped"],"answer":"D","explanation":"Opportunity cost is the value of the best choice you give up. The shift''s net pay, ₹900 − ₹150 = ₹750, is the best she skipped."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-010','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"Printing Plan A costs ₹200 a month plus ₹1 a page. Plan B costs ₹3 a page with no monthly fee. Gopal will print 60 to 90 pages a month. Which plan is cheaper?","options":["Plan B, at every amount in that range","Plan A, because ₹1 a page is lower","Plan A at 90 pages, Plan B at 60","Both cost the same at 75 pages"],"answer":"A","explanation":"At 60 pages, A costs ₹260 and B ₹180; at 90, A costs ₹290 and B ₹270. A only becomes cheaper above 100 pages, when the fixed fee is spread over more pages."}}'::jsonb, null,null,'draft','ai'),
  ('budget-50-30-20-007','budget', array['50-30-20','pocket-money'], 'platinum','mcq', '{"en":{"prompt":"Sana''s allowance is ₹2,000, split 50-30-20. Bus fares rise and her needs now cost ₹1,300. She wants to keep saving ₹400. What must her wants budget become?","options":["₹600","₹400","₹300","₹100"],"answer":"C","explanation":"₹2,000 − ₹1,300 needs − ₹400 savings leaves ₹300 for wants. Keeping her saving means giving up ₹300 of wants."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-011','budget', array['bills-and-emi'], 'platinum','mcq', '{"en":{"prompt":"Priya''s mother has an ₹8,000 card bill and ₹8,000 in her account. Paying only the minimum due would keep cash for a ₹3,000 trip. What is the main trade-off?","options":["None, because minimum due means no extra cost","The unpaid balance is charged high interest each month","Paying in full would lower her credit score","Interest starts only after one year"],"answer":"B","explanation":"Whatever is left unpaid is charged interest, often around 3% a month, so the trip ends up costing more than ₹3,000."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-007','budget', array['pocket-money'], 'diamond','mcq', '{"en":{"prompt":"Nila has saved ₹1,800 for a ₹9,000 laptop she will buy in 6 months. She can save ₹900 a month in months 1–3. Assume no interest. What equal amount must she save in each of months 4–6?","options":["₹1,500","₹1,200","₹2,400","₹1,400"],"answer":"A","explanation":"She still needs ₹9,000 − ₹1,800 − ₹2,700 = ₹4,500 after month 3. ₹4,500 ÷ 3 = ₹1,500 a month."}}'::jsonb, null,null,'draft','ai'),
  ('budget-pocket-money-008','budget', array['pocket-money','tracking-spending'], 'diamond','mcq', '{"en":{"prompt":"Ravi has ₹900 left from last month and gets ₹7,200. He pays ₹3,100 for essentials, saves ₹1,200, pays an ₹800 fee and wants ₹1,000 left at month end. Assume 4 weeks. What is his weekly limit for other spending?","options":["₹625","₹750","₹2,000","₹500"],"answer":"D","explanation":"₹900 + ₹7,200 − ₹3,100 − ₹1,200 − ₹800 − ₹1,000 = ₹2,000. Spread over 4 weeks, that is ₹500 a week."}}'::jsonb, null,null,'draft','ai'),
  ('budget-50-30-20-008','budget', array['50-30-20'], 'diamond','mcq', '{"en":{"prompt":"A family splits ₹30,000 a month by 50-30-20. Their income falls by 10%, but needs stay at ₹15,000. They keep saving 20% of the new income. How much is left for wants?","options":["₹8,100","₹9,000","₹6,600","₹6,000"],"answer":"C","explanation":"New income is ₹27,000 and 20% savings is ₹5,400. ₹27,000 − ₹15,000 − ₹5,400 = ₹6,600 for wants."}}'::jsonb, null,null,'draft','ai'),
  ('budget-bills-and-emi-012','budget', array['bills-and-emi'], 'diamond','mcq', '{"en":{"prompt":"A family buys a ₹24,000 fridge on EMI: ₹2,200 a month for 12 months. They have ₹3,000 spare each month and set aside ₹500 of it for emergencies. Which is true?","options":["It costs ₹2,200 extra, and ₹800 is left monthly","It costs ₹2,400 extra, and ₹300 is left monthly","It costs ₹2,400 extra, and ₹800 is left monthly","It costs nothing extra, and ₹300 is left monthly"],"answer":"B","explanation":"₹2,200 × 12 = ₹26,400, which is ₹2,400 more than the price. Each month ₹3,000 − ₹2,200 − ₹500 leaves ₹300."}}'::jsonb, null,null,'draft','ai'),
  ('budget-tracking-spending-008','budget', array['tracking-spending'], 'diamond','mcq', '{"en":{"prompt":"Harsha spends ₹30 on snacks every day. Assume 30-day months. He cuts down to snacks on only 10 days a month and saves the difference for a ₹4,800 phone. How many months will it take?","options":["6 months","5 months","16 months","8 months"],"answer":"D","explanation":"Before, he spent ₹900 a month; now he spends ₹300, so he saves ₹600 a month. ₹4,800 ÷ ₹600 = 8 months."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-001','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"In investing, what does the word \"risk\" mainly mean?","options":["The chance your money''s value falls or swings","The fee a bank charges to open an account","The interest rate printed on an FD receipt","The tax taken from a person''s salary"],"answer":"A","explanation":"Risk is the chance that an investment is worth less than you hoped, or even less than you put in. Values that move up and down a lot carry more risk."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-002','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"In general, how are risk and possible return linked?","options":["Higher return always comes with lower risk","Risk and return have no link at all","Low-risk options always give the highest return","Higher possible return usually comes with higher risk"],"answer":"D","explanation":"Options that could grow more are usually the ones that can also fall more. A chance of bigger reward comes with a chance of bigger loss."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-001','invest', array['diversification'], 'bronze','mcq', '{"en":{"prompt":"What does \"diversification\" mean when you invest money?","options":["Putting all your money in the one best option","Moving money often to chase quick gains","Spreading money across different kinds of options","Keeping all your savings as cash at home"],"answer":"C","explanation":"Diversification means not depending on just one thing. If one option does badly, the others can soften the blow."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-002','invest', array['diversification'], 'bronze','mcq', '{"en":{"prompt":"The saying \"Don''t put all your eggs in one basket\" teaches which money lesson?","options":["Always buy the cheapest thing available","Spread risk so one loss can''t wipe you out","Keep all savings in one bank account","Spend money before prices go up"],"answer":"B","explanation":"If all your money is in one place, one bad event can hurt all of it. Spreading it out limits the damage from any single loss."}}'::jsonb, null,null,'draft','ai'),
  ('invest-time-horizon-001','invest', array['time-horizon'], 'bronze','mcq', '{"en":{"prompt":"What is an investment''s \"time horizon\"?","options":["The hours the bank stays open each day","How long you plan to keep the money invested","The date a company first sold its shares","The time it takes to open an account"],"answer":"B","explanation":"Time horizon is how long until you need the money. It helps decide how much up-and-down movement the money can handle."}}'::jsonb, null,null,'draft','ai'),
  ('invest-time-horizon-002','invest', array['time-horizon','risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"Why can money for a goal many years away usually handle more ups and downs?","options":["There is more time to recover from falls","Long-term options never fall in value","Prices stop changing after five years","Banks guarantee all long-term investments"],"answer":"A","explanation":"Values can fall in the short run, but a long gap before you need the money gives time for them to recover. Recovery is still not guaranteed."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-001','invest', array['mutual-fund-basics'], 'bronze','mcq', '{"en":{"prompt":"What is a mutual fund, in simple words?","options":["A loan a bank gives to students","A savings account with a fixed interest rate","A government scheme that promises double money","Money pooled from many people and managed together"],"answer":"D","explanation":"A mutual fund collects money from many people and a manager invests it in many things. Its value can go up or down."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-002','invest', array['mutual-fund-basics'], 'bronze','mcq', '{"en":{"prompt":"In investing, what does \"SIP\" stand for?","options":["Safe Interest Payment","Savings Insurance Policy","Systematic Investment Plan","Simple Income Profit"],"answer":"C","explanation":"SIP means Systematic Investment Plan. It is a way of putting a fixed amount into a fund at regular times, such as every month."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-001','invest', array['stocks-basics'], 'bronze','mcq', '{"en":{"prompt":"If you own one share of a company, what do you actually own?","options":["A loan you gave to that company","A fixed deposit with that company","A small part of that company","A promise of the company''s profits"],"answer":"C","explanation":"A share is a small piece of ownership in a company. Its price can rise or fall with how the company and market do."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-002','invest', array['stocks-basics'], 'bronze','mcq', '{"en":{"prompt":"Can a company''s share price fall below the price you paid for it?","options":["No, share prices only rise over time","Yes, share prices can go down as well as up","No, the government fixes all share prices","Only if the company shuts down completely"],"answer":"B","explanation":"Share prices change every day based on buying and selling. They can fall below your buying price, so a loss is possible."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-001','invest', array['gold-and-fd'], 'bronze','mcq', '{"en":{"prompt":"Gold prices go up and down from day to day. What does this mean for someone who owns gold?","options":["Its value can rise or fall over time","Its value can only go up","It pays a fixed interest every month","It works exactly like cash in a bank"],"answer":"A","explanation":"Gold pays no fixed interest, and its price changes with demand. Its value can fall as well as rise."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-002','invest', array['gold-and-fd'], 'bronze','mcq', '{"en":{"prompt":"Which statement about the price of gold is true?","options":["It only ever goes up each year","The bank fixes it once every year","It stays the same for ten years at a time","It goes up and down; it is not fixed"],"answer":"D","explanation":"Gold''s price changes with demand and world events. It can fall as well as rise."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-003','invest', array['gold-and-fd','risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"Compared with shares, why is a bank FD usually called lower risk?","options":["It always earns more than shares","Its value rises whenever markets rise","It has no rules about taking money out","Its interest rate is fixed when you open it"],"answer":"D","explanation":"An FD''s rate is agreed at the start, so you know what it will pay. Share prices move every day, so their value is less certain."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-003','invest', array['mutual-fund-basics','diversification'], 'bronze','mcq', '{"en":{"prompt":"Why does one mutual fund usually hold shares of many different companies?","options":["So the fund can promise fixed returns","So investors never pay any charges","So one company''s fall hurts the fund less","So the fund''s value can never go down"],"answer":"C","explanation":"Holding many companies spreads risk, so one bad company has a smaller effect. The fund''s value can still go down."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-003','invest', array['risk-and-return'], 'bronze','mcq', '{"en":{"prompt":"What is \"survivorship bias\" in stories about money?","options":["Saving money to survive emergencies","Hearing only from winners, not from people who lost","Choosing safe options to avoid every loss","Believing old companies can never fail"],"answer":"B","explanation":"People who made money share their stories, while those who lost often stay quiet. So risky bets can look safer than they really are."}}'::jsonb, null,null,'draft','ai'),
  ('invest-time-horizon-003','invest', array['time-horizon','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Shreya needs ₹5,000 for exam fees in two months. Why could a high-risk option be a poor fit for this money?","options":["Its value could be down when she needs it","Risky options cannot be sold for a year","Exam fees cannot be paid from investments","Risky options always lose money in two months"],"answer":"A","explanation":"In a short time, a risky option may be below what she put in. She would then have less than ₹5,000 for her fees."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-003','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Arjun''s uncle keeps all his savings in shares of the one company he works for. What is the main danger?","options":["If it struggles, he may lose job and savings together","Shares of your own company cannot be sold","He will pay double tax on those shares","There is no danger if he trusts the company"],"answer":"A","explanation":"His salary and his savings both depend on the same company. One bad event could hit both at once."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-004','invest', array['risk-and-return'], 'silver','mcq', '{"en":{"prompt":"A message says: \"Invest ₹1,000, get ₹2,000 in one week, zero risk!\" What does the risk-return idea tell you?","options":["It is fine if a friend has already tried it","One week is enough time to double money safely","Small amounts like ₹1,000 carry no risk","High return with no risk is a big warning sign"],"answer":"D","explanation":"Big returns always come with big risk, so a promise of both is not believable. Such offers are often scams."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-003','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Kiran''s friend says a share \"will surely go up\" because it rose a lot last month. What is wrong with this thinking?","options":["Shares that rise must fall the next month","Share prices change only once a year","Past rises do not guarantee future rises","Prices rise only when profits are paid out"],"answer":"C","explanation":"A share''s past movement does not decide what happens next. Nobody can be sure a price will rise."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-004','invest', array['mutual-fund-basics'], 'silver','mcq', '{"en":{"prompt":"Fatima puts ₹500 into a mutual fund on the 5th of every month. What is this regular way of investing called?","options":["A lump-sum fixed deposit","A SIP (Systematic Investment Plan)","A monthly loan EMI","A one-time share purchase"],"answer":"B","explanation":"Putting a fixed amount into a fund at regular times is a SIP. A lump sum is a single large payment, and an EMI repays a loan."}}'::jsonb, null,null,'draft','ai'),
  ('invest-time-horizon-004','invest', array['time-horizon'], 'silver','mcq', '{"en":{"prompt":"Rahul is saving for a goal 10 years away. Ananya is saving for a phone in 6 months. Who can better handle short-term ups and downs?","options":["Ananya, because her amount is smaller","Rahul, because he has more time to recover","Both equally, since time does not matter","Neither, because values never change"],"answer":"B","explanation":"Rahul will not need his money for years, so a fall today has time to recover. Ananya needs hers soon, so a fall could leave her short."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-004','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Meena sells only tea at her stall. Her neighbour sells tea, snacks and juice. In a month when tea sales drop, who is likely hurt more?","options":["Meena, because all her income depends on tea","The neighbour, because she has more to manage","Both equally, since tea sales fell for both","Neither, because stalls always earn the same"],"answer":"A","explanation":"Meena has only one source of income, so a fall in tea sales hits all of it. Her neighbour still earns from snacks and juice."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-004','invest', array['gold-and-fd'], 'silver','mcq', '{"en":{"prompt":"Sunita''s grandmother says, \"Gold never loses value.\" Which statement is more accurate?","options":["Gold rises by a fixed amount every year","Banks guarantee the value of gold","Gold loses value only when made into jewellery","Gold prices can fall too, sometimes for years"],"answer":"D","explanation":"Gold''s price moves with demand and world events. It has had long periods of falling or flat prices."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-005','invest', array['mutual-fund-basics','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"A fund advert says, \"Mutual fund investments are subject to market risks.\" What does this mean?","options":["The fund promises you a fixed yearly return","Only the fund manager can lose money","Your money''s value can go down as well as up","Your money can never be taken out"],"answer":"C","explanation":"A fund''s value follows the market, so it can fall. That warning reminds investors that returns are not promised."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-005','invest', array['risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Vikram feels so worried that he cannot sleep when his investment drops 10%. What does this say about his \"risk tolerance\"?","options":["It is high; he enjoys big swings","Risk tolerance cannot be judged from feelings","It is low; big swings make him uneasy","Risk tolerance depends only on a person''s age"],"answer":"C","explanation":"Risk tolerance is how comfortable you are with your money going up and down. Strong worry after a small drop shows low tolerance."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-004','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Lakshmi owns a few shares of a company. News comes that the company''s profits have fallen sharply. What is likely to happen to her shares?","options":["Their price is fixed, so nothing changes","Their price may fall","She must pay a share of the losses","The bank will refund her original amount"],"answer":"B","explanation":"Share prices often fall when a company earns less, because fewer people want to buy. Her loss is limited to what she invested."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-005','invest', array['gold-and-fd'], 'silver','mcq', '{"en":{"prompt":"Imran puts ₹10,000 in a 1-year FD but needs the money after 4 months. What usually happens?","options":["He can break it early, often for less interest","He cannot get any money for the full year","He earns extra interest for leaving early","The bank keeps the whole ₹10,000 as a fine"],"answer":"A","explanation":"Most banks let you close an FD early but pay a lower rate or charge a small penalty. His original money is still returned."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-005','invest', array['diversification'], 'silver','mcq', '{"en":{"prompt":"Which example shows money spread across the widest mix of options?","options":["Ravi puts all savings in one company''s shares","Asha buys gold jewellery with all her savings","Tarun keeps all his savings in one FD","Pooja splits savings across an FD, gold and a fund"],"answer":"D","explanation":"Pooja''s money is in three different types of options. The others have everything in a single option."}}'::jsonb, null,null,'draft','ai'),
  ('invest-time-horizon-005','invest', array['time-horizon','risk-and-return'], 'silver','mcq', '{"en":{"prompt":"Why do many people lower the risk of their savings as the date of their goal gets close?","options":["Risky options stop working near goal dates","Banks require it in the final year","Low-risk options pay more near a goal date","A fall near the end leaves little time to recover"],"answer":"D","explanation":"Close to the goal, there is no time to wait for prices to come back. Lowering risk then protects the money that is needed soon."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-005','invest', array['stocks-basics'], 'silver','mcq', '{"en":{"prompt":"Siddharth bought a share at ₹200. It is now ₹150, and he has not sold it. What is true?","options":["He has already lost ₹50 in cash for sure","The price must return to ₹200 eventually","His loss is on paper; the price can still change","The company now owes him ₹50"],"answer":"C","explanation":"Until he sells, the ₹50 loss is not final, and the price may rise or fall further. Nothing guarantees it returns to ₹200."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-006','invest', array['diversification','risk-and-return'], 'gold','mcq', '{"en":{"prompt":"A fruit seller earns ₹300 a day each from mangoes, bananas and apples. Mango season fails, and mango income becomes zero. How much does she still earn per day?","options":["₹0","₹600","₹300","₹900"],"answer":"B","explanation":"Only the ₹300 from mangoes is lost, so bananas and apples still bring ₹600. Selling three fruits meant one bad season did not wipe her out."}}'::jsonb, 'invest-risk-and-diversification',null,'draft','ai'),
  ('invest-risk-and-return-006','invest', array['risk-and-return'], 'gold','mcq', '{"en":{"prompt":"Priya''s ₹10,000 investment falls 20% in year one and rises 20% in year two. What is it worth now? (Example numbers; ignore fees.)","options":["₹9,600","₹10,000","₹8,000","₹10,400"],"answer":"A","explanation":"After the fall it is ₹8,000, and 20% of ₹8,000 is ₹1,600, giving ₹9,600. A rise has to be bigger than the fall to get back to the start."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-007','invest', array['diversification'], 'gold','mcq', '{"en":{"prompt":"Ravi puts ₹5,000 in option X and ₹5,000 in option Y. In one example year, X falls 10% and Y rises 6%. What is his total at year end?","options":["₹9,800","₹9,000","₹10,600","₹9,600"],"answer":"A","explanation":"X becomes ₹4,500 and Y becomes ₹5,300, which adds to ₹9,800. Splitting the money made the loss smaller than putting it all in X."}}'::jsonb, null,null,'draft','ai'),
  ('invest-gold-and-fd-006','invest', array['gold-and-fd'], 'gold','mcq', '{"en":{"prompt":"Anjali puts ₹20,000 in a 1-year FD. Assume 7% interest a year and ignore tax. How much will she have at the end?","options":["₹20,140","₹27,000","₹21,000","₹21,400"],"answer":"D","explanation":"7% of ₹20,000 is ₹1,400, so she ends with ₹21,400. A fixed rate makes the FD result easy to know in advance."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-006','invest', array['mutual-fund-basics','time-horizon'], 'gold','mcq', '{"en":{"prompt":"Kavya invests ₹500 every month through a SIP for 3 years. How much money has she put in, before any gains or losses?","options":["₹1,500","₹6,000","₹18,000","₹15,000"],"answer":"C","explanation":"3 years is 36 months, and 36 × ₹500 = ₹18,000. The fund''s value could end above or below this amount."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-007','invest', array['risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Option A grows about 6% each year with small changes. Option B has averaged more, but in some years fell 15%. What is the main trade-off? (Example numbers.)","options":["A is riskier because it grows slowly","B may grow more but can drop sharply","B is safer because its average is higher","There is no trade-off; B is simply better"],"answer":"B","explanation":"B''s higher average comes with bigger falls, while A is steadier but grows slowly. Choosing between them means weighing growth against the chance of loss."}}'::jsonb, null,'invest-risk-and-return','draft','ai'),
  ('invest-time-horizon-006','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Neha needs ₹30,000 in 6 months. Arvind''s goal is 12 years away. Both look at an option that can fall 20% in a bad year. Why might it suit them differently?","options":["Neha''s smaller goal makes a loss impossible","Arvind has time to recover; Neha may not","Arvind''s long wait guarantees him a profit","It suits both equally; time doesn''t matter"],"answer":"B","explanation":"A bad year just before Neha needs her money could leave her short. Arvind has years for prices to recover, though even that is not guaranteed."}}'::jsonb, null,'invest-risk-and-return','draft','ai'),
  ('invest-time-horizon-007','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Divya and Karan invest in the same option for 10 years. After a 15% fall, Divya stays invested while Karan sells in panic. Whose choice locks in the loss?","options":["Karan''s, because selling makes the fall final","Divya''s, because staying makes losses bigger","Neither, since losses are final once prices fall","Both equally, since selling changes nothing"],"answer":"A","explanation":"A fall is only a loss on paper until you sell. By selling, Karan turned it into a real loss, while Divya''s value can still change."}}'::jsonb, null,'invest-risk-and-return','draft','ai'),
  ('invest-risk-and-return-008','invest', array['risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Ramesh''s FD earns an assumed 5% a year, while prices rise 6% a year. Why is his \"safe\" FD losing value in real terms?","options":["The bank cuts 6% from his deposit yearly","Share market falls reduce his FD by 1%","Interest is paid only when prices fall","Prices rise faster than his money grows"],"answer":"D","explanation":"His money grows 5%, but things cost 6% more, so it buys a little less each year. Low risk does not always mean no loss of buying power."}}'::jsonb, null,'invest-risk-and-return','draft','ai'),
  ('invest-time-horizon-008','invest', array['time-horizon','risk-and-return'], 'platinum','mcq', '{"en":{"prompt":"Sana has ₹15,000: ₹10,000 is her emergency fund and ₹5,000 is for a goal 8 years away. Why might she treat these two parts differently?","options":["The larger part should always take more risk","Both parts have the same time horizon","Emergency money must be ready; long-term money can ride ups and downs","Long-term money must be kept as cash at home"],"answer":"C","explanation":"An emergency can come any day, so that money must not be down when needed. Money for 8 years ahead has time to handle some swings."}}'::jsonb, null,'invest-risk-and-return','draft','ai'),
  ('invest-diversification-008','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Portfolio A has 5 shares, all banks. Portfolio B has 5 shares from banking, medicine, food, phones and power. Which is more diversified, and why?","options":["A, because banks are always safe","Both, because each holds five shares","B, because one industry''s trouble hits less of it","A, because fewer industries are easier to track"],"answer":"C","explanation":"If banks have a bad year, all of A suffers but only one-fifth of B does. Diversifying across industries spreads that risk."}}'::jsonb, null,'invest-diversification','draft','ai'),
  ('invest-diversification-009','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Diversification is useful, but there are limits. Which of these can diversification NOT do?","options":["Reduce harm from one bad investment","Guarantee that you never lose money","Spread your money across different options","Make one company''s failure hurt less"],"answer":"B","explanation":"Diversification softens losses from any one option. When most markets fall together, a spread-out mix can still lose money."}}'::jsonb, null,'invest-diversification','draft','ai'),
  ('invest-diversification-010','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Spreading money across many options lowers risk. What is the trade-off?","options":["You won''t get the full gain of the top performer","Your money becomes locked for many years","Your total return is guaranteed to be lower","You must pay extra tax on each option"],"answer":"A","explanation":"Only part of your money is in whichever option does best, so your gain is smaller than if it were all there. In return, a single failure hurts less."}}'::jsonb, null,'invest-diversification','draft','ai'),
  ('invest-diversification-011','invest', array['diversification'], 'platinum','mcq', '{"en":{"prompt":"Asif puts ₹10,000 into one option. Bhavna splits ₹10,000 equally across five options, including Asif''s. That option falls to zero; the others stay flat. How much does each lose?","options":["Both lose ₹10,000","Asif ₹10,000; Bhavna ₹5,000","Asif ₹2,000; Bhavna ₹10,000","Asif ₹10,000; Bhavna ₹2,000"],"answer":"D","explanation":"Bhavna had only ₹10,000 ÷ 5 = ₹2,000 in the failed option. Asif had everything in it, so he lost it all."}}'::jsonb, null,'invest-diversification','draft','ai'),
  ('invest-diversification-012','invest', array['diversification','mutual-fund-basics'], 'platinum','mcq', '{"en":{"prompt":"Gopal owns two mutual funds and thinks he is well diversified. But both funds mostly hold the same ten big companies. What is the problem?","options":["Owning two funds is against the rules","Funds holding big companies cannot fall","He is spread across too many companies","His money is still bunched in the same companies"],"answer":"D","explanation":"If the same ten companies do badly, both funds fall together. Real diversification means holding things that don''t all depend on the same companies."}}'::jsonb, null,'invest-diversification','draft','ai'),
  ('invest-time-horizon-009','invest', array['time-horizon','risk-and-return'], 'diamond','mcq', '{"en":{"prompt":"Farah has ₹40,000. She needs ₹15,000 for fees next month and wants ₹10,000 kept ready for emergencies. The rest is for a goal 6 years away. How much is free for that long-term goal?","options":["₹25,000","₹30,000","₹15,000","₹40,000"],"answer":"C","explanation":"Fees and emergencies need ₹15,000 + ₹10,000 = ₹25,000, leaving ₹40,000 − ₹25,000 = ₹15,000. Only money not needed soon can wait out ups and downs."}}'::jsonb, null,null,'draft','ai'),
  ('invest-mutual-fund-basics-007','invest', array['mutual-fund-basics','time-horizon'], 'diamond','mcq', '{"en":{"prompt":"Manoj wants ₹24,000 in 2 years, saved equally each month through a SIP. He gets a ₹4,800 gift to start. Ignoring gains and losses, how much must he add monthly?","options":["₹1,000","₹800","₹1,600","₹200"],"answer":"B","explanation":"He still needs ₹24,000 − ₹4,800 = ₹19,200 over 24 months, which is ₹800 a month. Real returns could make the final amount higher or lower."}}'::jsonb, null,null,'draft','ai'),
  ('invest-diversification-013','invest', array['diversification','gold-and-fd'], 'diamond','mcq', '{"en":{"prompt":"Nisha splits ₹20,000: ₹10,000 in an FD at an assumed 7%, ₹5,000 in gold and ₹5,000 in a share fund. In one example year, gold rises 10% and the fund falls 20%. Year-end total?","options":["₹20,200","₹19,800","₹19,400","₹21,200"],"answer":"A","explanation":"The FD becomes ₹10,700, gold ₹5,500 and the fund ₹4,000, totalling ₹20,200. Each part''s change must be applied to its own amount."}}'::jsonb, null,null,'draft','ai'),
  ('invest-risk-and-return-009','invest', array['risk-and-return'], 'diamond','mcq', '{"en":{"prompt":"Rohan invests ₹10,000. In example years, it rises 50%, then falls 50%, then rises 20%. Ignoring fees, what is it worth after three years?","options":["₹9,000","₹12,000","₹7,500","₹10,000"],"answer":"A","explanation":"₹10,000 becomes ₹15,000, then ₹7,500, then ₹9,000. A 50% fall undoes more than a 50% rise, so the percentages cannot simply be added."}}'::jsonb, null,null,'draft','ai'),
  ('invest-stocks-basics-006','invest', array['stocks-basics'], 'diamond','mcq', '{"en":{"prompt":"Tanvi buys 20 shares at ₹100 each. She gets ₹40 in total dividends (a share of company profits), then sells all at ₹110 each. Ignoring fees and tax, what is her total return?","options":["10%","2%","14%","12%"],"answer":"D","explanation":"She paid ₹2,000 and gained ₹200 from the price rise plus ₹40 in dividends, so ₹240. ₹240 ÷ ₹2,000 = 12%."}}'::jsonb, null,null,'draft','ai'),
  ('safety-otp-and-pin-001','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"A caller says he is from your bank and your KYC expires today. He asks for the OTP you just received. What should you do?","options":["Share it fast so your account is not blocked","Share only the first two digits","Hang up and call the number on your bank card","Ask him to send the request by message"],"answer":"C","explanation":"Banks never ask for your OTP, PIN or password on a call or message. Hang up and call your bank yourself on the number printed on your card."}}'::jsonb, 'safety-never-share-otp',null,'draft','ai'),
  ('safety-phishing-001','safety', array['phishing','ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"A message says: \"You won ₹25 lakh! Pay a ₹2,000 processing fee to claim it.\" What is the biggest red flag?","options":["You must pay money first to get the prize","The prize amount is too small to be real","The message did not ask for your OTP","It came as a message, not a letter"],"answer":"A","explanation":"Real prizes never charge you a fee before you get them. Asking you to pay first is a classic scam sign."}}'::jsonb, 'safety-spot-the-scam',null,'draft','ai'),
  ('safety-upi-fraud-001','safety', array['upi-fraud','otp-and-pin'], 'bronze','mcq', '{"en":{"prompt":"Kavya is selling old books. The buyer says, \"Enter your UPI PIN so you can receive ₹300.\" What is true?","options":["You must enter your PIN to receive any money","You never need a UPI PIN to receive money","A PIN is needed only for amounts above ₹200","A PIN is needed only when the buyer is a stranger"],"answer":"B","explanation":"Money comes into your account without your PIN. Entering your UPI PIN always approves money going out."}}'::jsonb, null,'safety-upi-and-otp','draft','ai'),
  ('safety-otp-and-pin-002','safety', array['otp-and-pin'], 'bronze','mcq', '{"en":{"prompt":"Your bank sends you a one-time password (OTP). Who is it meant for?","options":["Bank staff who call to check your account","A delivery person who asks for it at the door","A friend helping you set up your app","Only you, to approve your own payment or login"],"answer":"D","explanation":"An OTP proves that you yourself are approving an action. Anyone who has it can act as you, so it is never shared."}}'::jsonb, null,'safety-upi-and-otp','draft','ai'),
  ('safety-upi-fraud-002','safety', array['upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"On a UPI app, what happens when you approve a \"collect request\" with your UPI PIN?","options":["Money comes into your account","Your KYC details get updated","Money goes out of your account","You receive a cashback reward"],"answer":"C","explanation":"A collect request asks you to pay someone. Approving it with your PIN sends money from your account to them."}}'::jsonb, null,'safety-upi-and-otp','draft','ai'),
  ('safety-otp-and-pin-003','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"Who should know your UPI PIN?","options":["Only you","You and your bank''s customer care","You and your closest friend","Anyone who sends you money"],"answer":"A","explanation":"Your UPI PIN works like the key to your account. No real bank, friend or buyer ever needs it."}}'::jsonb, null,'safety-upi-and-otp','draft','ai'),
  ('safety-otp-and-pin-004','safety', array['otp-and-pin','upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"Which of these is the safest habit for your UPI PIN?","options":["Use your birth year so it is easy to remember","Cover the keypad and never write the PIN down","Save it in your phone notes for quick access","Use 1234 so you can type it fast"],"answer":"B","explanation":"Hiding the keypad and keeping the PIN only in your memory stops others from seeing or finding it. Birth years and simple numbers are easy to guess."}}'::jsonb, null,'safety-upi-and-otp','draft','ai'),
  ('safety-insurance-basics-001','safety', array['insurance-basics'], 'bronze','mcq', '{"en":{"prompt":"What is insurance mainly for?","options":["Growing your money quickly like a business","Getting a fixed income every month","Protecting you from a big loss you cannot afford","Avoiding all taxes on your savings"],"answer":"C","explanation":"With insurance, many people pay small amounts so that the few who face a big loss get help. Its job is protection, not growing money."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-002','safety', array['insurance-basics'], 'bronze','mcq', '{"en":{"prompt":"In insurance, what is a \"premium\"?","options":["The money the insurer pays you after a claim","A bonus for staying healthy all year","A fine for making a claim late","The amount you pay to keep your cover active"],"answer":"D","explanation":"The premium is what you pay, yearly or monthly, to stay insured. The money the insurer pays you is the claim amount."}}'::jsonb, null,null,'draft','ai'),
  ('safety-phishing-002','safety', array['phishing'], 'bronze','mcq', '{"en":{"prompt":"What is phishing?","options":["An official SMS from your bank about a new rule","A fake message pretending to be trusted, to steal details","A virus that only affects computers","A loan offer from a registered bank"],"answer":"B","explanation":"Phishing messages copy the look of a bank or company to trick you. They try to get your passwords, OTPs or card details."}}'::jsonb, null,null,'draft','ai'),
  ('safety-phishing-003','safety', array['phishing'], 'bronze','mcq', '{"en":{"prompt":"An SMS says your bank account will be blocked and gives a link like \"bank-kyc-update.xyz\". What should you do?","options":["Tap it and fill in details if the logo looks right","Reply to the SMS to ask if it is genuine","Tap it but do not enter your PIN","Ignore the link and check your bank''s official app"],"answer":"D","explanation":"Links in urgent messages often lead to fake pages that steal your details. Checking through your bank''s own app or number is the safe way."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-001','safety', array['fake-loan-apps'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a warning sign of a fake loan app?","options":["It asks to access all your contacts and photos","It shows the interest rate clearly before you borrow","It asks for your documents to check who you are","It names an RBI-registered lender you can verify"],"answer":"A","explanation":"Fake loan apps take your contacts and photos so they can harass and shame you later. A real lender has no need for them."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-001','safety', array['ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"A scheme pays its old members using money from new members, not from real earnings. What is this called?","options":["A Ponzi scheme","A fixed deposit","A recurring deposit","An insurance policy"],"answer":"A","explanation":"A Ponzi scheme pays old members with new members'' money. It collapses when new money stops coming in."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-002','safety', array['ponzi-and-chit-scams'], 'bronze','mcq', '{"en":{"prompt":"Which promise is the clearest sign of an investment scam?","options":["Returns can go up or down","Please read all documents carefully","Past returns do not promise future returns","Your money will surely double in one month"],"answer":"D","explanation":"No one can guarantee such high returns, so a sure-shot promise is a big red flag. Honest offers warn you that returns can change."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-003','safety', array['upi-fraud'], 'bronze','mcq', '{"en":{"prompt":"If you lose money in an online fraud, which national cybercrime helpline should you call?","options":["108","101","1930","139"],"answer":"C","explanation":"1930 is the national cybercrime helpline, and you can also report at cybercrime.gov.in. Calling quickly gives the best chance of stopping the money."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-004','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Someone online offers Arjun ₹5,000 to let money pass through his bank account and forward it on. Arjun will not steal anything himself. What is the risk?","options":["None, because Arjun does not steal anything","He becomes part of a fraud; his account can be frozen","Only the person paying him can get in trouble","He only has to pay a little tax on ₹5,000"],"answer":"B","explanation":"Stolen money moving through your account makes you a \"money mule\" and the trail leads to you. Your account can be frozen and you can face a police case."}}'::jsonb, 'safety-money-mule',null,'draft','ai'),
  ('safety-phishing-004','safety', array['phishing'], 'silver','mcq', '{"en":{"prompt":"Rahul gets an SMS: \"Your electricity will be cut at 9 pm today. Call this mobile number to update your bill.\" What is the safest move?","options":["Call the number quickly to avoid the power cut","Pay the bill through the link in the SMS","Check the bill on the official board website or office","Share his account number so they can verify him"],"answer":"C","explanation":"Scammers use fear and a short deadline to rush you. Checking through the official website or office tells you if any bill is really due."}}'::jsonb, null,'safety-spot-the-scam','draft','ai'),
  ('safety-fake-loan-apps-002','safety', array['fake-loan-apps'], 'silver','mcq', '{"en":{"prompt":"Imran needs ₹3,000. An app offers \"Instant loan, no documents, approved in 2 minutes\" and wants access to his contacts. How should he see this?","options":["It is fast, so it must be modern and safe","No documents means the lender is friendly","It is fine if he deletes the app after the loan","These are warning signs; check if the lender is RBI-registered"],"answer":"D","explanation":"No checks, very fast approval and contact access are typical signs of a fake loan app. Real lenders are registered with the RBI and check documents."}}'::jsonb, null,'safety-spot-the-scam','draft','ai'),
  ('safety-ponzi-and-chit-scams-003','safety', array['ponzi-and-chit-scams'], 'silver','mcq', '{"en":{"prompt":"Lakshmi''s neighbour says: \"Pay ₹1,000 to join, then earn ₹500 for every friend you bring in.\" There is no real product. What is this most likely?","options":["A pyramid-style scheme that will collapse","A safe savings plan","A bank recurring deposit","A government welfare scheme"],"answer":"A","explanation":"When earnings come only from recruiting new people, the scheme runs out of new members and collapses. Most people who join late lose their money."}}'::jsonb, null,'safety-spot-the-scam','draft','ai'),
  ('safety-ponzi-and-chit-scams-004','safety', array['ponzi-and-chit-scams'], 'silver','mcq', '{"en":{"prompt":"Sunita''s aunt wants to join a chit fund run by someone new to the area. He promises very high returns and shows no papers. What should she ask first?","options":["How many people have already joined?","Can I pay my share in cash?","Is this chit fund officially registered?","Will I get a gift for joining?"],"answer":"C","explanation":"Registered chit funds must follow rules and keep records, so members can complain if something goes wrong. An unregistered one can vanish with everyone''s money."}}'::jsonb, null,'safety-spot-the-scam','draft','ai'),
  ('safety-ponzi-and-chit-scams-005','safety', array['ponzi-and-chit-scams','phishing'], 'silver','mcq', '{"en":{"prompt":"Divya joins an online task: \"Like videos, earn ₹200 each.\" She is paid ₹200 at first. Now she is asked to deposit ₹5,000 to unlock \"premium tasks\". What is happening?","options":["This is a normal step in online part-time jobs","The small payment built trust before a bigger scam","Her earnings are being taxed by the company","The company is checking that her bank works"],"answer":"B","explanation":"Task scams pay a little at first so you trust them. Then they ask you to put in bigger amounts and disappear with it."}}'::jsonb, null,'safety-spot-the-scam','draft','ai'),
  ('safety-upi-fraud-005','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Mohan is selling his old phone online. The buyer sends a QR code and says, \"Scan this and enter your PIN to receive ₹4,000.\" What is true?","options":["Scanning and entering the PIN is how you receive money","Scan it, but try a small amount first","Scanning a QR code and entering a PIN sends money out","Scan it only if the buyer seems polite"],"answer":"C","explanation":"Scanning a QR code is for paying, not receiving. You never need to scan anything or enter a PIN to get money."}}'::jsonb, null,null,'draft','ai'),
  ('safety-otp-and-pin-005','safety', array['otp-and-pin'], 'silver','mcq', '{"en":{"prompt":"A \"customer care\" caller asks Pooja to install a screen-sharing app so he can fix her failed payment. What should she do?","options":["Refuse; such apps let strangers control her phone","Install it so they can fix the problem faster","Install it but close it after five minutes","Install it if the caller knows her name"],"answer":"A","explanation":"Screen-sharing apps let the caller see your OTPs and PIN and even control your phone. Real support never needs this."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-006','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"Ravi''s UPI payment failed. He searches online, finds a \"helpline\" number, and the person asks for his UPI PIN to refund him. What is the right move?","options":["Share the PIN, since he called them himself","Use the help section in the UPI app or bank''s site","Give the PIN but keep the OTP secret","Wait a day and then share the PIN"],"answer":"B","explanation":"Fake helpline numbers are often posted online to catch people. A refund never needs your PIN, so use the help options inside the official app."}}'::jsonb, null,null,'draft','ai'),
  ('safety-phishing-005','safety', array['phishing'], 'silver','mcq', '{"en":{"prompt":"A message offers Ayesha a ₹30,000-a-month data entry job. She must first pay a ₹1,500 registration fee. What is the best response?","options":["Pay, since the salary is much bigger than the fee","Pay half now and the rest after joining","Pay only after getting a receipt from them","Do not pay; real employers do not charge to hire"],"answer":"D","explanation":"Real jobs pay you; they do not ask you to pay to get hired. An upfront fee for a job is a common scam."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-003','safety', array['insurance-basics'], 'silver','mcq', '{"en":{"prompt":"Suresh is the only earning member of his family. What problem does life insurance help with?","options":["It pays his family if he dies, replacing lost income","It makes his salary grow faster","It pays for the family''s daily groceries","It returns double the premium every year"],"answer":"A","explanation":"Life insurance pays a sum to the family if the insured person dies. This helps them manage without his income."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-004','safety', array['insurance-basics'], 'silver','mcq', '{"en":{"prompt":"Meena''s family has health insurance. Her father needs surgery costing ₹80,000. How does the insurance help?","options":["It gives a loan they must repay with interest","It pays covered costs as per the policy terms","It pays back all the premiums they ever paid","It helps only if they claim a year later"],"answer":"B","explanation":"Health insurance pays for covered hospital costs up to the limits in the policy. That is why reading what is covered matters."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-003','safety', array['fake-loan-apps'], 'silver','mcq', '{"en":{"prompt":"A loan app threatens to send Karthik''s photos to his contacts unless he pays extra \"fees\". What should he do?","options":["Pay quickly so the threats stop","Delete the app and tell no one","Borrow from another app to pay them","Save proof and report at cybercrime.gov.in or 1930"],"answer":"D","explanation":"Paying usually leads to more demands. Keeping proof and reporting to the cybercrime helpline lets officials act against the harassers."}}'::jsonb, null,null,'draft','ai'),
  ('safety-otp-and-pin-006','safety', array['otp-and-pin'], 'silver','mcq', '{"en":{"prompt":"Nikhil''s friend borrows his phone and asks for the OTP that just arrived \"to log in to a game\". The SMS says it is for a bank payment. What should Nikhil do?","options":["Share it, since it is only a game login","Share it but change his PIN later","Share it if the friend promises to repay","Read the SMS: it is for a payment, so refuse"],"answer":"D","explanation":"An OTP message tells you what it approves, and this one approves a payment. Sharing it would let money leave his account."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-007','safety', array['upi-fraud'], 'silver','mcq', '{"en":{"prompt":"A stranger calls Lata: \"I sent ₹2,000 to your UPI by mistake. Please return it.\" She has not checked her account yet. What should she do?","options":["Check her own balance; if no credit, send nothing","Send ₹2,000 back right away","Approve the collect request he sends","Send half now and half after checking"],"answer":"A","explanation":"Scammers fake \"wrong transfer\" stories with fake SMS or collect requests. Only your own bank app or statement shows whether money really came in."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-006','safety', array['ponzi-and-chit-scams'], 'gold','mcq', '{"en":{"prompt":"A scheme promises a \"guaranteed\" 10% return every month. Without compounding, what yearly return is that?","options":["10%","12%","120%","1.2%"],"answer":"C","explanation":"10% a month × 12 months = 120% a year, many times what a bank FD pays (around 6–7% a year; rates vary). A guaranteed return that high is a strong scam sign."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-004','safety', array['fake-loan-apps'], 'gold','mcq', '{"en":{"prompt":"A loan app approves ₹5,000 for Rohan but cuts a ₹1,000 \"processing fee\", so he gets ₹4,000. He must repay ₹5,500 in 30 days. How much more does he repay than he received?","options":["₹500","₹1,000","₹5,500","₹1,500"],"answer":"D","explanation":"He repays ₹5,500 but only got ₹4,000, so he pays ₹1,500 extra. That is 37.5% of what he received in just one month."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-005','safety', array['fake-loan-apps'], 'gold','mcq', '{"en":{"prompt":"A loan app charges 2% interest per week on a ₹3,000 loan (no compounding). How much interest is due after 8 weeks?","options":["₹60","₹480","₹240","₹600"],"answer":"B","explanation":"2% of ₹3,000 is ₹60 a week, and ₹60 × 8 weeks = ₹480. Weekly rates look small but add up fast."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-007','safety', array['ponzi-and-chit-scams'], 'gold','mcq', '{"en":{"prompt":"A scheme must pay old members ₹45,000 every month and earns no real profit. New members join with ₹1,500 each. How many new members must join each month just to cover payouts?","options":["30","3","15","45"],"answer":"A","explanation":"₹45,000 ÷ ₹1,500 = 30 new members every month. When new members stop joining, the payouts stop and the scheme collapses."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-005','safety', array['insurance-basics'], 'gold','mcq', '{"en":{"prompt":"Priya''s health policy pays 80% of covered hospital costs. She has a covered bill of ₹50,000. How much of the bill does Priya pay herself?","options":["₹40,000","₹10,000","₹6,000","₹16,000"],"answer":"B","explanation":"The insurer pays 80% of ₹50,000, which is ₹40,000. Priya pays the remaining 20%, which is ₹10,000."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-008','safety', array['ponzi-and-chit-scams'], 'platinum','mcq', '{"en":{"prompt":"Farhan compares two chit groups. Group X is registered, has written rules and gives modest returns. Group Y is unregistered and promises double returns. What is the key trade-off?","options":["Y promises more but gives no legal protection if it vanishes","X is riskier because its returns are lower","Both are equally safe if friends have joined","Y is safer because there is no paperwork to go wrong"],"answer":"A","explanation":"A registered chit fund must follow rules and can be held to account. Y''s bigger promise comes with no protection if the organiser disappears."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-006','safety', array['insurance-basics'], 'platinum','mcq', '{"en":{"prompt":"Ananya compares two health policies. Policy 1 costs ₹4,000 a year and covers up to ₹2 lakh. Policy 2 costs ₹2,500 a year and covers up to ₹50,000. What is the main trade-off?","options":["Policy 1 is a waste because its premium is higher","Policy 2 covers more because it is cheaper","Policy 2 saves ₹1,500 yearly but covers big bills less","Both give the same cover; only the price differs"],"answer":"C","explanation":"The cheaper policy saves ₹1,500 a year, but any bill above ₹50,000 would be paid from the family''s pocket. A lower premium usually means less cover."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-006','safety', array['fake-loan-apps'], 'platinum','mcq', '{"en":{"prompt":"Vikram needs ₹10,000. A bank takes 3 days and checks documents. An unknown app pays in 2 minutes with no checks but wants his contacts. What does he risk for the app''s speed?","options":["Nothing, since both give the same amount","His privacy, hidden fees and possible harassment","Only a slightly lower credit score","Losing the bank''s cashback offer"],"answer":"B","explanation":"Unchecked instant apps often hide huge fees and misuse contacts to harass borrowers. The bank is slower, but its terms are clear and regulated."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-008','safety', array['upi-fraud','otp-and-pin'], 'platinum','mcq', '{"en":{"prompt":"Shruti uses UPI every day. She plans to keep only small amounts in the account linked to UPI and the rest in another account. What is the trade-off?","options":["Having two accounts is always unsafe","She will no longer need a UPI PIN","She will earn double interest on her money","Less money is at risk, but moving money takes extra steps"],"answer":"D","explanation":"If her UPI is ever misused, only the small balance is exposed. The cost is the extra effort of moving money when she needs more."}}'::jsonb, null,null,'draft','ai'),
  ('safety-phishing-006','safety', array['phishing'], 'platinum','mcq', '{"en":{"prompt":"A message from what looks like Gopal''s cousin''s number says: \"Emergency! Send ₹8,000 now, I''ll explain later.\" Calling back takes time. Which choice best balances speed and safety?","options":["Send it now, since family comes first","Call the cousin on a known number before sending","Send ₹4,000 now as a middle path","Ask the sender to share a photo as proof"],"answer":"B","explanation":"A quick call to a number you already know confirms the story in minutes. Scammers can copy names, photos and even hack accounts, so a message alone is not proof."}}'::jsonb, null,null,'draft','ai'),
  ('safety-upi-fraud-009','safety', array['upi-fraud'], 'diamond','mcq', '{"en":{"prompt":"Sanjay sees ₹15,000 debited by a UPI payment he never made. Which order of actions is best?","options":["Inform bank to block UPI, call 1930, then file online with screenshots","Post on social media, wait for the bank, then call 1930","Delete the messages, change phones, tell the bank next week","Call the receiver''s number and ask for a refund first"],"answer":"A","explanation":"Blocking first stops more money leaving, and a quick 1930 report can help freeze the stolen money. A complaint on cybercrime.gov.in with saved screenshots gives a proper record."}}'::jsonb, null,null,'draft','ai'),
  ('safety-otp-and-pin-007','safety', array['otp-and-pin','upi-fraud'], 'diamond','mcq', '{"en":{"prompt":"Neha read out an OTP to a fake \"bank\" caller five minutes ago. No money has left yet. Which plan makes the most sense?","options":["Wait for a debit SMS, then decide whether to call the bank","Call bank to block account, report to 1930, change PIN","Call the caller back and ask him to cancel it","Change her phone number first, tell the bank next month"],"answer":"B","explanation":"Acting before any money moves gives the best chance to stop it. Blocking, reporting and changing her PIN close each door the scammer could use."}}'::jsonb, null,null,'draft','ai'),
  ('safety-fake-loan-apps-007','safety', array['fake-loan-apps'], 'diamond','mcq', '{"en":{"prompt":"Zoya borrowed ₹2,000 from a loan app. It now demands ₹9,000 and threatens to message her contacts. Which plan is best?","options":["Pay ₹9,000 now, then uninstall the app","Borrow from a second app to repay the first","Save threats, tell family, report to 1930, remove app permissions","Ignore it and only change her phone number"],"answer":"C","explanation":"Paying or borrowing more feeds the trap, while proof and an official report let police act. Telling family early also takes away the scammer''s power to shame her."}}'::jsonb, null,null,'draft','ai'),
  ('safety-ponzi-and-chit-scams-009','safety', array['ponzi-and-chit-scams'], 'diamond','mcq', '{"en":{"prompt":"Raju put ₹20,000 into a scheme promising 5% a week. It paid him ₹1,000 a week for 6 weeks, then asked for ₹10,000 more to \"unlock\" his money. Which plan is wisest?","options":["Pay ₹10,000, since he has already earned ₹6,000","Stop paying, keep records, report it; he is still ₹14,000 down","Bring in friends so he can recover ₹14,000","Pay only ₹5,000 to reduce his risk"],"answer":"B","explanation":"He got back ₹6,000 of his ₹20,000, so he is ₹14,000 down, and paying more only adds to the loss. Keeping records and reporting is the only step that can help."}}'::jsonb, null,null,'draft','ai'),
  ('safety-insurance-basics-007','safety', array['insurance-basics'], 'diamond','mcq', '{"en":{"prompt":"Hari''s family wants protection against a big hospital bill. Which order of steps makes the most sense?","options":["Pick the cheapest policy, then read the terms after a claim","Buy whatever policy a friend has, without reading it","Wait until someone falls sick, then buy a policy","List needs, compare cover and exclusions, then check claim process"],"answer":"D","explanation":"Knowing what you need and what each policy covers or leaves out avoids nasty surprises later. Checking how claims work makes sure help arrives when needed."}}'::jsonb, null,null,'draft','ai'),
  ('save-emergency-fund-001','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"In the reel, Peter A paid his ₹3,000 phone repair with zero stress. What had he done?","options":["Saved ₹200 a month in a separate pot","Borrowed the money from a friend","Took a loan from an instant-loan app","Spent his pocket money on games"],"answer":"A","explanation":"Peter A had been saving ₹200 every month in a separate \"don''t touch\" pot. When the phone broke, the money was already there."}}'::jsonb, 'save-emergency-fund',null,'draft','ai'),
  ('save-emergency-fund-002','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"What is an emergency fund?","options":["Money saved to buy a new phone","Money borrowed when you run short","Money spent during festival sales","Money kept only for sudden, unplanned costs"],"answer":"D","explanation":"An emergency fund is set aside only for surprises like repairs or medical bills. Because it is ready, you do not need to borrow when trouble comes."}}'::jsonb, null,'save-emergency-fund','draft','ai'),
  ('save-emergency-fund-003','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"Which of these is a real reason to use your emergency fund?","options":["A sudden hospital bill for a family member","A new video game that just launched","A big discount on branded shoes","A friend''s birthday party this weekend"],"answer":"A","explanation":"A hospital bill is unplanned and cannot wait, which is exactly what an emergency fund is for. Games, sales and parties are wants you can plan or skip."}}'::jsonb, null,'save-emergency-fund','draft','ai'),
  ('save-emergency-fund-004','save', array['emergency-fund'], 'bronze','mcq', '{"en":{"prompt":"Why should you keep your emergency fund separate from your spending money?","options":["So it earns double the interest","So your parents cannot see it","So you can lend it to friends easily","So you do not spend it by accident"],"answer":"D","explanation":"When the fund is mixed with everyday money, it slowly gets spent on small things. Keeping it apart protects it for a real emergency."}}'::jsonb, null,'save-emergency-fund','draft','ai'),
  ('save-savings-goals-001','save', array['savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Which of these is the clearest savings goal?","options":["Save ₹6,000 for a cycle in 6 months","Save some money soon","Save whatever is left at month end","Save more than my friends do"],"answer":"A","explanation":"A clear goal has an amount and a deadline. Then you can work out how much to save each month (here ₹1,000)."}}'::jsonb, null,'save-emergency-fund','draft','ai'),
  ('save-emergency-fund-005','save', array['emergency-fund','savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Kavya gets small pocket money and has no emergency fund yet. What is a good way to start one?","options":["Wait until she earns a full salary","Save only when she gets birthday money","Borrow money to fill it at once","Save a small amount, like ₹100, every month"],"answer":"D","explanation":"Even ₹100 a month adds up, and the habit matters more than the size. Starting small now is better than waiting for a big amount."}}'::jsonb, null,'save-emergency-fund','draft','ai'),
  ('save-bank-accounts-001','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"A bank pays you a small extra amount for keeping money in a savings account. What is it called?","options":["Interest","Dividend","EMI","Cashback"],"answer":"A","explanation":"Interest is what the bank pays you for keeping your money with it. The bank uses deposits to give loans and shares part of what it earns."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-002','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"Why is a bank savings account safer than a piggy bank for your savings?","options":["The bank doubles your money every year","You can never take the money out","The bank pays your bills for you","Money is protected from loss and also earns interest"],"answer":"D","explanation":"Money at home can be lost, stolen or spent on impulse, while a bank keeps it safe. A savings account also adds interest to it."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-003','save', array['bank-accounts'], 'bronze','mcq', '{"en":{"prompt":"What is a fixed deposit (FD)?","options":["Money left in a bank for a fixed time and rate","A loan the bank gives to students","A card used to pay in shops","An account you can top up daily"],"answer":"A","explanation":"In an FD you keep money with the bank for a fixed period. In return the bank pays an interest rate fixed at the start."}}'::jsonb, null,null,'draft','ai'),
  ('save-simple-interest-001','save', array['simple-interest'], 'bronze','mcq', '{"en":{"prompt":"What is simple interest?","options":["Interest paid on interest as well","Interest paid only on the money you first put in","Interest that changes every single day","A fee the bank takes from you"],"answer":"B","explanation":"Simple interest is worked out only on the original amount. It stays the same every year."}}'::jsonb, null,null,'draft','ai'),
  ('save-simple-interest-002','save', array['simple-interest'], 'bronze','mcq', '{"en":{"prompt":"Arun puts ₹2,000 in a bank. What is this first amount called?","options":["Interest","Profit","Inflation","Principal"],"answer":"D","explanation":"The principal is the starting amount you deposit or borrow. Interest is calculated on it."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-001','save', array['compound-interest'], 'bronze','mcq', '{"en":{"prompt":"What is compound interest?","options":["Interest earned on your money plus past interest","Interest earned only on the first deposit","Interest that is paid just once","A penalty for taking money out early"],"answer":"A","explanation":"With compound interest, the interest is added to your money and then earns interest too. This makes savings grow faster over time."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-001','save', array['inflation'], 'bronze','mcq', '{"en":{"prompt":"What does inflation mean?","options":["Prices rise over time, so money buys less","Prices fall, so money buys more","Banks pay more interest each year","Your savings grow by themselves"],"answer":"A","explanation":"Inflation is the general rise in prices over time. The same ₹100 buys fewer things later."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-002','save', array['inflation'], 'bronze','mcq', '{"en":{"prompt":"A samosa cost ₹10 five years ago. Today the same samosa costs ₹15. What is this an example of?","options":["Simple interest","Inflation","Compound interest","Saving"],"answer":"B","explanation":"The same item now costs more rupees, which is inflation. Your money buys less than it did before."}}'::jsonb, null,null,'draft','ai'),
  ('save-savings-goals-002','save', array['savings-goals'], 'bronze','mcq', '{"en":{"prompt":"Kiran wants a ₹1,500 cricket bat. Which of these is a clear savings goal?","options":["Save some money sometime this year","Save whatever is left each month","Save ₹300 a month for 5 months","Borrow the money from friends"],"answer":"C","explanation":"A clear goal names the amount, the time and the monthly step. ₹300 × 5 months = ₹1,500."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-002','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"In the reel, two Mortys each save ₹500 a month until 58. One starts at 18, one at 28. Why does Early Morty end with far more?","options":["He got a much higher interest rate","He saved far more money each month","Late Morty took out his savings early","His money had ten more years to compound"],"answer":"D","explanation":"Both saved the same ₹500 at the same assumed rate, but Early Morty''s returns had more years to earn returns of their own. Time is what made his money snowball."}}'::jsonb, 'save-compounding',null,'draft','ai'),
  ('save-emergency-fund-006','save', array['emergency-fund'], 'silver','mcq', '{"en":{"prompt":"Riya has ₹2,000 in her emergency fund. Her friends plan a ₹1,500 day trip next month. What should she do?","options":["Keep the fund and save separately for the trip","Use the fund, since she can refill it","Use half the fund and borrow the rest","Close the fund to have more fun money"],"answer":"A","explanation":"A planned trip is not an emergency, so it needs its own savings. Keeping the fund untouched means she is still ready for real surprises."}}'::jsonb, null,null,'draft','ai'),
  ('save-emergency-fund-007','save', array['emergency-fund'], 'silver','mcq', '{"en":{"prompt":"Kiran used ₹1,000 from her emergency fund to pay for her brother''s medicine. What should she do next?","options":["Leave it empty since the emergency is over","Slowly refill the fund from her pocket money","Stop saving because emergencies are rare","Spend the rest of the fund too"],"answer":"B","explanation":"Emergencies can happen again, so the fund should be built back up. Adding a little each month refills it over time."}}'::jsonb, null,null,'draft','ai'),
  ('save-emergency-fund-008','save', array['emergency-fund','bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Where is the best place to keep an emergency fund?","options":["A 5-year deposit that is hard to break","Lent to a friend who will return it","A savings account you can use quickly","In things whose price goes up and down"],"answer":"C","explanation":"Emergency money must be safe and ready the same day you need it. A savings account gives quick access without the value going up and down."}}'::jsonb, null,null,'draft','ai'),
  ('save-savings-goals-003','save', array['savings-goals'], 'silver','mcq', '{"en":{"prompt":"Meena wants ₹3,600 for a school trip in 6 months. How much should she save each month?","options":["₹300","₹500","₹600","₹720"],"answer":"C","explanation":"Divide the goal by the months: ₹3,600 ÷ 6 = ₹600. Saving that each month gets her there on time."}}'::jsonb, null,null,'draft','ai'),
  ('save-savings-goals-004','save', array['savings-goals'], 'silver','mcq', '{"en":{"prompt":"Rahul gets ₹1,000 pocket money a month and wants to save for headphones. Which habit will help him most?","options":["Save whatever is left at the end","Save only in months he spends less","Decide each week if he feels like saving","Put ₹200 aside the day he gets the money"],"answer":"D","explanation":"Saving first, on the day money comes in, makes saving automatic. Waiting until month end often leaves nothing to save."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-004','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Sana keeps her ₹5,000 birthday savings in a tin at home. Compared with a savings account, what is she missing?","options":["The chance to double it every year","Safety and the interest the bank would pay","Free money the bank gives every month","Nothing, a tin works the same"],"answer":"B","explanation":"In a bank, her money is protected and earns interest. In a tin it can be lost or stolen and never grows."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-005','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Vikram will not touch ₹10,000 for 2 years. Why might an FD suit him better than a savings account?","options":["FDs let you take money out any time free","FDs always double your money in 2 years","FDs usually pay more interest for a locked period","FDs pay no interest but are safer"],"answer":"C","explanation":"An FD usually offers a higher rate because you agree to leave the money for a fixed time. Since Vikram does not need it soon, he can accept that lock."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-006','save', array['bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Divya''s savings account balance went up by ₹25, but she deposited nothing. What is the most likely reason?","options":["Someone sent her money by mistake","The bank gave her a loan","Prices in the market went down","The bank added interest to her account"],"answer":"D","explanation":"Banks add interest to savings accounts from time to time. That small increase is the bank paying her for keeping money there."}}'::jsonb, null,null,'draft','ai'),
  ('save-simple-interest-003','save', array['simple-interest'], 'silver','mcq', '{"en":{"prompt":"Priya puts ₹1,000 in a deposit at 5% simple interest a year. How much interest does she earn in 1 year? (Assume the rate stays fixed.)","options":["₹5","₹50","₹500","₹1,050"],"answer":"B","explanation":"5% of ₹1,000 is ₹50. ₹1,050 is the total amount, not the interest."}}'::jsonb, null,null,'draft','ai'),
  ('save-simple-interest-004','save', array['simple-interest'], 'silver','mcq', '{"en":{"prompt":"Two deposits pay simple interest on ₹5,000 for 1 year: one at 4%, one at 6%. How much more does the 6% one earn?","options":["₹2","₹100","₹200","₹300"],"answer":"B","explanation":"At 4% you earn ₹200 and at 6% you earn ₹300. The difference is ₹100."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-003','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"Ankit and Neha each deposit ₹1,000 at the same rate. Ankit takes out his interest every year; Neha leaves hers in. Who has more after 5 years?","options":["Neha, because her interest also earns interest","Ankit, because he took money out often","Both have the same total","Ankit, because withdrawals add bonus interest"],"answer":"A","explanation":"Neha''s interest stays in and earns more interest, so her money compounds. Ankit''s money stays at ₹1,000, so it only earns simple interest."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-004','save', array['compound-interest'], 'silver','mcq', '{"en":{"prompt":"Same amount, same yearly rate, same 10 years. Which grows a little more: interest added once a year or every month?","options":["Interest added once a year","Both grow exactly the same","Neither grows, the rate is the same","Interest added every month"],"answer":"D","explanation":"When interest is added more often, it starts earning interest sooner. So monthly compounding ends slightly higher."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-003','save', array['inflation'], 'silver','mcq', '{"en":{"prompt":"Prices rise about 6% a year. Lakshmi keeps ₹1,000 in a drawer for a year. What happens to it?","options":["Still ₹1,000, but it buys less than before","It grows to ₹1,060 by itself","It drops to ₹940 in notes","Nothing changes at all"],"answer":"A","explanation":"The notes stay ₹1,000, but things cost about 6% more. So the same money buys fewer things."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-004','save', array['inflation','bank-accounts'], 'silver','mcq', '{"en":{"prompt":"Your savings account pays 3% a year, and prices rise 6% a year. What happens to what your savings can buy? (Example rates; real rates vary.)","options":["It grows, because you earn interest","It falls, because prices rise faster than interest","It stays exactly the same","It doubles every few years"],"answer":"B","explanation":"Your money grows 3% but prices grow 6%, so each year it buys a little less. Interest must beat inflation for buying power to grow."}}'::jsonb, null,null,'draft','ai'),
  ('save-simple-interest-005','save', array['simple-interest'], 'gold','mcq', '{"en":{"prompt":"Anjali puts ₹10,000 in a deposit at 8% simple interest a year for 3 years. What is the total amount at the end? (Assume a fixed rate.)","options":["₹2,400","₹10,800","₹12,400","₹12,597"],"answer":"C","explanation":"Interest each year is 8% of ₹10,000 = ₹800, so 3 years give ₹2,400. Total = ₹10,000 + ₹2,400 = ₹12,400."}}'::jsonb, null,'save-magic-of-compounding','draft','ai'),
  ('save-compound-interest-005','save', array['compound-interest'], 'gold','mcq', '{"en":{"prompt":"Suresh deposits ₹10,000 at 10% a year, compounded yearly, for 2 years. How much does he have at the end? (Assume a fixed rate.)","options":["₹11,000","₹12,000","₹12,100","₹12,210"],"answer":"C","explanation":"Year 1: ₹10,000 + ₹1,000 = ₹11,000. Year 2: ₹11,000 + ₹1,100 = ₹12,100."}}'::jsonb, null,'save-magic-of-compounding','draft','ai'),
  ('save-compound-interest-006','save', array['compound-interest','simple-interest'], 'gold','mcq', '{"en":{"prompt":"₹5,000 is kept for 2 years at 10% a year. How much more interest does compound interest earn than simple interest? (Assume yearly compounding.)","options":["₹0","₹50","₹100","₹500"],"answer":"B","explanation":"Simple interest gives ₹500 + ₹500 = ₹1,000. Compound gives ₹500 + ₹550 = ₹1,050, which is ₹50 more."}}'::jsonb, null,'save-magic-of-compounding','draft','ai'),
  ('save-inflation-005','save', array['inflation'], 'gold','mcq', '{"en":{"prompt":"Rick says money that sits still slowly loses value. If prices rise 5% a year, what will ₹200 of groceries cost next year? (Assume 5% exactly.)","options":["₹190","₹200","₹205","₹210"],"answer":"D","explanation":"5% of ₹200 is ₹10, so the same groceries cost ₹210. ₹200 kept still will no longer buy them."}}'::jsonb, 'save-inflation','save-magic-of-compounding','draft','ai'),
  ('save-compound-interest-007','save', array['compound-interest'], 'gold','mcq', '{"en":{"prompt":"The rule of 72 says: years to double ≈ 72 ÷ yearly rate. At 8% a year, compounded, about how long until money doubles?","options":["About 4 years","About 9 years","About 12 years","About 64 years"],"answer":"B","explanation":"72 ÷ 8 = 9, so money roughly doubles in 9 years at 8%. This is a quick estimate, not an exact answer."}}'::jsonb, null,'save-magic-of-compounding','draft','ai'),
  ('save-emergency-fund-009','save', array['emergency-fund','savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Zoya has ₹5,000 saved and no emergency fund. Her phone works, but she wants a ₹5,000 upgrade. Which choice best balances both needs?","options":["Spend all ₹5,000 now on the upgrade","Never upgrade, since saving is always better","Keep some as an emergency fund, save more for later","Buy the phone and borrow if trouble comes"],"answer":"C","explanation":"Her phone still works, so the upgrade can wait while she keeps a cushion for surprises. Saving a little more lets her have both, without borrowing later."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-007','save', array['bank-accounts'], 'platinum','mcq', '{"en":{"prompt":"Rohan may need ₹8,000 any week for his mother''s medicine. Why might a savings account suit him better than a 1-year FD, despite lower interest?","options":["He can take money out anytime without a penalty","Savings accounts always pay more than FDs","FD money can never be taken out","Savings accounts grow faster with compounding"],"answer":"A","explanation":"Breaking an FD early usually means lower interest or a penalty. When money may be needed at short notice, easy access matters more than a slightly higher rate."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-006','save', array['inflation','bank-accounts'], 'platinum','mcq', '{"en":{"prompt":"An FD pays 7% a year and a savings account pays 3%. Prices rise 6% a year. Which is true? (Example rates; real rates vary.)","options":["Both grow buying power","FD buying power grows slightly; savings account''s falls","Both lose buying power","Savings account grows; FD loses"],"answer":"B","explanation":"Buying power grows only when interest beats inflation: 7% beats 6% by a little, but 3% falls 3% behind. So the FD just keeps ahead while the savings account loses ground."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-008','save', array['compound-interest','savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Isha, 17, can save ₹500 a month from now, or ₹1,000 a month starting at 27. Both stop at 60. Assume 8% a year (not a promise). Which ends bigger?","options":["₹1,000 from 27, since she pays in more","Both end with exactly the same","₹500 from 17, even though she pays in less","It depends only on the total paid in"],"answer":"C","explanation":"Starting at 17 grows to about ₹22 lakh, while starting at 27 grows to about ₹19 lakh, even though she pays in less. The extra 10 years of compounding outweigh the bigger monthly amount."}}'::jsonb, null,null,'draft','ai'),
  ('save-savings-goals-005','save', array['savings-goals'], 'platinum','mcq', '{"en":{"prompt":"Kabir wants a ₹12,000 laptop. He can save ₹1,000 a month for a year, or buy now paying ₹1,200 a month for a year. What is the trade-off?","options":["Both options cost exactly ₹12,000","Saving first costs ₹2,400 more","Buying now costs only ₹200 extra","Buying now costs ₹2,400 extra; waiting costs nothing extra"],"answer":"D","explanation":"Paying ₹1,200 × 12 = ₹14,400 is ₹2,400 more than the price. Saving first means waiting a year, but he pays only ₹12,000."}}'::jsonb, null,null,'draft','ai'),
  ('save-savings-goals-006','save', array['savings-goals'], 'diamond','mcq', '{"en":{"prompt":"Ananya needs ₹30,000 for college fees in 2 years. She already has ₹6,000 saved. Ignoring interest, how much must she save each month?","options":["₹750","₹1,000","₹1,250","₹2,000"],"answer":"B","explanation":"She still needs ₹30,000 − ₹6,000 = ₹24,000. Over 24 months that is ₹24,000 ÷ 24 = ₹1,000 a month."}}'::jsonb, null,null,'draft','ai'),
  ('save-emergency-fund-010','save', array['emergency-fund','savings-goals'], 'diamond','mcq', '{"en":{"prompt":"Nikhil saves ₹1,500 a month. First he builds a ₹6,000 emergency fund, then saves for a ₹9,000 course. Ignoring interest, how many months until both are done?","options":["4 months","6 months","10 months","15 months"],"answer":"C","explanation":"He needs ₹6,000 + ₹9,000 = ₹15,000 in total. At ₹1,500 a month, that takes 15,000 ÷ 1,500 = 10 months."}}'::jsonb, null,null,'draft','ai'),
  ('save-inflation-007','save', array['inflation','compound-interest'], 'diamond','mcq', '{"en":{"prompt":"A coaching course costs ₹20,000 today. Fees rise 10% every year. What will it cost in 2 years? (Assume exactly 10% a year.)","options":["₹22,000","₹24,000","₹24,200","₹40,000"],"answer":"C","explanation":"After 1 year: ₹20,000 + ₹2,000 = ₹22,000. After 2 years: ₹22,000 + ₹2,200 = ₹24,200, because each rise is on the new price."}}'::jsonb, null,null,'draft','ai'),
  ('save-compound-interest-009','save', array['compound-interest'], 'diamond','mcq', '{"en":{"prompt":"Pooja deposits ₹5,000 now and another ₹5,000 after 1 year, at 10% a year compounded yearly. How much does she have after 2 years? (Assume a fixed rate.)","options":["₹11,000","₹11,500","₹11,550","₹12,100"],"answer":"C","explanation":"The first ₹5,000 grows for 2 years to ₹6,050, and the second grows for 1 year to ₹5,500. Together that is ₹11,550."}}'::jsonb, null,null,'draft','ai'),
  ('save-bank-accounts-008','save', array['bank-accounts','simple-interest','inflation'], 'diamond','mcq', '{"en":{"prompt":"Asif puts ₹10,000 in an FD at 7% simple interest for 2 years. A ₹10,000 laptop''s price rises 6% each year. After 2 years, can he afford it? (Example rates.)","options":["Yes, with about ₹160 to spare","Yes, with ₹1,400 to spare","No, he is about ₹200 short","No, the laptop then costs ₹12,000"],"answer":"A","explanation":"His FD becomes ₹10,000 + ₹1,400 = ₹11,400, while the laptop becomes ₹10,000 × 1.06 × 1.06 = ₹11,236. He has about ₹164 left over."}}'::jsonb, null,null,'draft','ai')
